SELECT status, opened_cohort, stddev_balance FROM (SELECT status, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, ROUND(STDDEV(balance), 2) AS stddev_balance FROM accounts GROUP BY status, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS t WHERE stddev_balance >= 61;
